const body = $input.first().json.body || $input.first().json;
const clean = (s) => String(s == null ? '' : s).replace(/[^A-Za-z0-9_ \u4e00-\u9fa5\-\.%\:#\/]/g, '').trim();
const machineId = clean(body.machine_id);
return {
  json: {
    machine_id: machineId,
    machine_id_like: machineId ? (machineId + '%') : '',
  }
};

const rows = Array.isArray($input.first().json) ? $input.first().json : [$input.first().json];
const m = rows && rows[0];
if (!m || !m.tool_id) {
  return { json: { ok: false, answer: '未找到该机台的实时状态快照（dt_state_snapshot 无记录，请确认机台ID正确）', table_data: null, jump_timestamp: null, jump_machine_id: null, sources: [{ type: 'n8n', workflow: 'get_machine_status', execution_id: $execution.id }] } };
}
const headers = ['机台','状态','模式','当前Lot','告警码','快照时间'];
const vals = rows.map(r => [String(r.tool_id||''), String(r.machine_state||''), String(r.machine_mode||''), String(r.current_lot_id||''), String(r.current_alarm_code||''), String(r.snapshot_ts_utc||'')]);
let answer = `机台 ${m.tool_id}：状态 ${m.machine_state || '未知'}；模式 ${m.machine_mode || 'N/A'}；当前Lot ${m.current_lot_id || '无'}`;
if (m.current_alarm_code) answer += `；当前告警 ${m.current_alarm_code}`;
if (m.snapshot_ts_utc) answer += `；快照时间 ${m.snapshot_ts_utc}`;
return { json: { ok: true, answer, table_data: { headers, rows: vals }, jump_timestamp: m.snapshot_ts_utc ? String(m.snapshot_ts_utc) : null, jump_machine_id: String(m.tool_id), sources: [{ type: 'n8n', workflow: 'get_machine_status', execution_id: $execution.id }] } };
